cat > /tmp/inverse2.py << 'EOF'
import RNA, random, sys
from multiprocessing import Pool

target='......(......((((.....))))......)......................'

def worker(seed):
    random.seed(seed)
    best_dist=999
    best_seq=None
    for trial in range(200):
        start=''.join(random.choice('ACGU') for _ in range(55))
        try:
            seq,dist=RNA.inverse_fold(start, target)
        except Exception:
            continue
        if len(seq)!=55:
            continue
        if dist==0:
            fc=RNA.fold_compound(seq)
            mfe,e=fc.mfe()
            if mfe==target:
                return seq
        if dist<best_dist:
            best_dist=dist
            best_seq=seq
    return (best_seq, best_dist)

if __name__=='__main__':
    nproc=64
    seeds=list(range(nproc*10))
    with Pool(nproc) as p:
        for r in p.imap_unordered(worker, seeds):
            if isinstance(r,str):
                print('SOLVED',r)
                sys.stdout.flush()
                p.terminate()
                sys.exit(0)
        print('DONE no solution')
EOF
